UPDATE public.grammar_lessons l
SET exercises = $grammar$[{"id":"countable-uncountable-ex-01","type":"multiple_choice","question":"I have ___ book on my desk.","options":["a","an","two"],"correct_answer":"a","explanation":"Book đếm được, số ít và bắt đầu bằng âm /b/: a book.","distractor_breakdowns":[{"option":"a","isCorrect":true,"pedagogicalReason":"Book đếm được, số ít và bắt đầu bằng âm /b/: a book."},{"option":"an","isCorrect":false,"pedagogicalReason":"Không chính xác. Mạo từ \"an\" chỉ đứng trước danh từ đếm được số ít phát âm bắt đầu bằng một nguyên âm."},{"option":"two","isCorrect":false,"pedagogicalReason":"Không chính xác. Phương án \"two\" không thỏa mãn quy tắc ngữ pháp hoặc sự hòa hợp cú pháp trong cấu trúc câu này."}],"difficulty":1},{"id":"countable-uncountable-ex-02","type":"multiple_choice","question":"She has ___ apples.","options":["two","a","an"],"correct_answer":"two","explanation":"Apples là số nhiều, có thể đi với số đếm two.","distractor_breakdowns":[{"option":"two","isCorrect":true,"pedagogicalReason":"Apples là số nhiều, có thể đi với số đếm two."},{"option":"a","isCorrect":false,"pedagogicalReason":"Không chính xác. Mạo từ \"a\" chỉ đứng trước danh từ đếm được số ít phát âm bắt đầu bằng một phụ âm."},{"option":"an","isCorrect":false,"pedagogicalReason":"Không chính xác. Mạo từ \"an\" chỉ đứng trước danh từ đếm được số ít phát âm bắt đầu bằng một nguyên âm."}],"difficulty":1},{"id":"countable-uncountable-ex-03","type":"multiple_choice","question":"I need ___ water. (some / a)","options":["some","a"],"correct_answer":"some","explanation":"Water không đếm được; dùng some water.","distractor_breakdowns":[{"option":"some","isCorrect":true,"pedagogicalReason":"Water không đếm được; dùng some water."},{"option":"a","isCorrect":false,"pedagogicalReason":"Không chính xác. Mạo từ \"a\" chỉ đứng trước danh từ đếm được số ít phát âm bắt đầu bằng một phụ âm."}],"difficulty":1},{"id":"countable-uncountable-ex-04","type":"fill_blank","question":"We bought two ___ of water. (bottle)","options":[],"correct_answer":"bottles","explanation":"Đếm đơn vị chứa nước: two bottles of water.","distractor_breakdowns":[{"option":"bottles","isCorrect":true,"pedagogicalReason":"Đếm đơn vị chứa nước: two bottles of water."},{"option":"bottle","isCorrect":false,"pedagogicalReason":"Không chính xác. Sau số đếm \"two\", danh từ đếm được chỉ đơn vị chứa \"bottle\" phải ở dạng số nhiều \"bottles\"."},{"option":"bottles of","isCorrect":false,"pedagogicalReason":"Không chính xác. Từ \"of\" đã có sẵn trong câu sau chỗ trống, điền thừa từ nối."}],"difficulty":1},{"id":"countable-uncountable-ex-05","type":"multiple_choice","question":"Câu sau đúng ngữ pháp không? → \"I have two books.\"","options":["Đúng","Sai"],"correct_answer":"Đúng","explanation":"Books đếm được và ở dạng số nhiều sau two.","distractor_breakdowns":[{"option":"Đúng","isCorrect":true,"pedagogicalReason":"Books đếm được và ở dạng số nhiều sau two."},{"option":"Sai","isCorrect":false,"pedagogicalReason":"Không chính xác. Khẳng định này là chính xác về mặt ngữ pháp, không phải là phát biểu sai."}],"difficulty":1},{"id":"countable-uncountable-ex-06","type":"multiple_choice","question":"Câu sau đúng ngữ pháp không? → \"She gave me two advices.\"","options":["Đúng","Sai"],"correct_answer":"Sai","explanation":"Advice không đếm được; nói two pieces of advice.","distractor_breakdowns":[{"option":"Đúng","isCorrect":false,"pedagogicalReason":"Không chính xác. Khẳng định này không phản ánh đúng quy tắc ngữ pháp của câu đã cho."},{"option":"Sai","isCorrect":true,"pedagogicalReason":"Advice không đếm được; nói two pieces of advice."}],"difficulty":1},{"id":"countable-uncountable-ex-07","type":"error_correction","question":"Which sentence is incorrect?","options":["I have two books.","I need some water.","I need a water to drink."],"correct_answer":"I need a water to drink.","explanation":"Khi nói chung về nước, dùng some water; a water chỉ có thể dùng trong ngữ cảnh gọi một phần nước.","distractor_breakdowns":[{"option":"I have two books.","isCorrect":false,"pedagogicalReason":"Không chính xác. Từ hoặc cụm từ \"I have two books.\" được sử dụng hoàn toàn đúng ngữ pháp trong câu, không phải là lỗi sai cần sửa."},{"option":"I need some water.","isCorrect":false,"pedagogicalReason":"Không chính xác. Từ hoặc cụm từ \"I need some water.\" được sử dụng hoàn toàn đúng ngữ pháp trong câu, không phải là lỗi sai cần sửa."},{"option":"I need a water to drink.","isCorrect":true,"pedagogicalReason":"Khi nói chung về nước, dùng some water; a water chỉ có thể dùng trong ngữ cảnh gọi một phần nước."}],"difficulty":1},{"id":"countable-uncountable-ex-08","type":"multiple_choice","question":"Which noun is usually uncountable?","options":["furniture","chair","table"],"correct_answer":"furniture","explanation":"Furniture không có dạng số nhiều furnitures trong tiếng Anh chuẩn.","distractor_breakdowns":[{"option":"furniture","isCorrect":true,"pedagogicalReason":"Furniture không có dạng số nhiều furnitures trong tiếng Anh chuẩn."},{"option":"chair","isCorrect":false,"pedagogicalReason":"Không chính xác. Phương án \"chair\" không thỏa mãn quy tắc ngữ pháp hoặc sự hòa hợp cú pháp trong cấu trúc câu này."},{"option":"table","isCorrect":false,"pedagogicalReason":"Không chính xác. Phương án \"table\" không thỏa mãn quy tắc ngữ pháp hoặc sự hòa hợp cú pháp trong cấu trúc câu này."}],"difficulty":1},{"id":"countable-uncountable-ex-09","type":"multiple_choice","question":"She gave me a piece of ___. (advice / advices)","options":["advice","advices"],"correct_answer":"advice","explanation":"Advice không thêm -s; dùng a piece of advice.","distractor_breakdowns":[{"option":"advice","isCorrect":true,"pedagogicalReason":"Advice không thêm -s; dùng a piece of advice."},{"option":"advices","isCorrect":false,"pedagogicalReason":"Không chính xác. Phương án \"advices\" không thỏa mãn quy tắc ngữ pháp hoặc sự hòa hợp cú pháp trong cấu trúc câu này."}],"difficulty":1},{"id":"countable-uncountable-ex-10","type":"multiple_choice","question":"Choose the natural phrase for two individual items of furniture.","options":["two pieces of furniture","two furnitures","two furniture"],"correct_answer":"two pieces of furniture","explanation":"Đếm furniture qua đơn vị: two pieces of furniture.","distractor_breakdowns":[{"option":"two pieces of furniture","isCorrect":true,"pedagogicalReason":"Đếm furniture qua đơn vị: two pieces of furniture."},{"option":"two furnitures","isCorrect":false,"pedagogicalReason":"Không chính xác. Phương án \"two furnitures\" không thỏa mãn quy tắc ngữ pháp hoặc sự hòa hợp cú pháp trong cấu trúc câu này."},{"option":"two furniture","isCorrect":false,"pedagogicalReason":"Không chính xác. Phương án \"two furniture\" không thỏa mãn quy tắc ngữ pháp hoặc sự hòa hợp cú pháp trong cấu trúc câu này."}],"difficulty":1},{"id":"countable-uncountable-ex-11","type":"fill_blank","question":"There are three ___ on the table. (apple)","options":[],"correct_answer":"apples","explanation":"Sau three, danh từ đếm được apple chuyển thành apples.","distractor_breakdowns":[{"option":"apples","isCorrect":true,"pedagogicalReason":"Sau three, danh từ đếm được apple chuyển thành apples."},{"option":"apple","isCorrect":false,"pedagogicalReason":"Không chính xác. Sau số đếm \"three\", danh từ đếm được \"apple\" phải chuyển thành dạng số nhiều \"apples\"."},{"option":"apples of","isCorrect":false,"pedagogicalReason":"Không chính xác. Không cần giới từ \"of\" sau danh từ đếm được trực tiếp."}],"difficulty":1},{"id":"countable-uncountable-ex-12","type":"multiple_choice","question":"Which phrase names one apple?","options":["an apple","a apple","one apples"],"correct_answer":"an apple","explanation":"Apple bắt đầu bằng âm nguyên âm: an apple.","distractor_breakdowns":[{"option":"an apple","isCorrect":true,"pedagogicalReason":"Apple bắt đầu bằng âm nguyên âm: an apple."},{"option":"a apple","isCorrect":false,"pedagogicalReason":"Không chính xác. Phương án \"a apple\" không thỏa mãn quy tắc ngữ pháp hoặc sự hòa hợp cú pháp trong cấu trúc câu này."},{"option":"one apples","isCorrect":false,"pedagogicalReason":"Không chính xác. Phương án \"one apples\" không thỏa mãn quy tắc ngữ pháp hoặc sự hòa hợp cú pháp trong cấu trúc câu này."}],"difficulty":1},{"id":"countable-uncountable-ex-13","type":"multiple_choice","question":"Choose the correct **article**: I saw ___ dog in the park.","options":["a","an","some","any"],"correct_answer":"a","explanation":"“Dog” là danh từ đếm được số ít và bắt đầu bằng âm phụ âm, nên dùng “a”. “An” dùng trước âm nguyên âm, còn “some/any” không phù hợp với danh từ đếm được số ít ở câu này.","distractor_breakdowns":[{"option":"a","isCorrect":true,"pedagogicalReason":"“Dog” là danh từ đếm được số ít và bắt đầu bằng âm phụ âm, nên dùng “a”. “An” dùng trước âm nguyên âm, còn “some/any” không phù hợp với danh từ đếm được số ít ở câu này."},{"option":"an","isCorrect":false,"pedagogicalReason":"Không chính xác. “An” dùng trước âm nguyên âm, còn “some/any” không phù hợp với danh từ đếm được số ít ở câu này."},{"option":"some","isCorrect":false,"pedagogicalReason":"Không chính xác. Some/any” không phù hợp với danh từ đếm được số ít ở câu này."},{"option":"any","isCorrect":false,"pedagogicalReason":"Không chính xác. Any” không phù hợp với danh từ đếm được số ít ở câu này."}],"difficulty":1},{"id":"countable-uncountable-ex-14","type":"multiple_choice","question":"Choose the correct **plural noun**: There are three ___ on the table.","options":["cup","cups","milk","rice"],"correct_answer":"cups","explanation":"Sau số đếm “three”, cần danh từ đếm được số nhiều, nên “cups” đúng. “Cup” là số ít, còn “milk” và “rice” là danh từ không đếm được nên không dùng trực tiếp với số đếm.","distractor_breakdowns":[{"option":"cup","isCorrect":false,"pedagogicalReason":"Không chính xác. “Cup” là số ít, còn “milk” và “rice” là danh từ không đếm được nên không dùng trực tiếp với số đếm."},{"option":"cups","isCorrect":true,"pedagogicalReason":"Sau số đếm “three”, cần danh từ đếm được số nhiều, nên “cups” đúng. “Cup” là số ít, còn “milk” và “rice” là danh từ không đếm được nên không dùng trực tiếp với số đếm."},{"option":"milk","isCorrect":false,"pedagogicalReason":"Không chính xác. “milk” và “rice” là danh từ không đếm được nên không dùng trực tiếp với số đếm."},{"option":"rice","isCorrect":false,"pedagogicalReason":"Không chính xác. “rice” là danh từ không đếm được nên không dùng trực tiếp với số đếm."}],"difficulty":1},{"id":"countable-uncountable-ex-15","type":"multiple_choice","question":"Choose the correct **quantifier**: We don't have ___ rice for dinner.","options":["many","any","a","an"],"correct_answer":"any","explanation":"“Rice” là danh từ không đếm được; trong câu phủ định thường dùng “any”. “Many” dùng với danh từ đếm được số nhiều, còn “a/an” không dùng trực tiếp với danh từ không đếm được.","distractor_breakdowns":[{"option":"many","isCorrect":false,"pedagogicalReason":"Không chính xác. “Many” dùng với danh từ đếm được số nhiều, còn “a/an” không dùng trực tiếp với danh từ không đếm được."},{"option":"any","isCorrect":true,"pedagogicalReason":"“Rice” là danh từ không đếm được; trong câu phủ định thường dùng “any”. “Many” dùng với danh từ đếm được số nhiều, còn “a/an” không dùng trực tiếp với danh từ không đếm được."},{"option":"a","isCorrect":false,"pedagogicalReason":"Không chính xác. A/an” không dùng trực tiếp với danh từ không đếm được."},{"option":"an","isCorrect":false,"pedagogicalReason":"Không chính xác. An” không dùng trực tiếp với danh từ không đếm được."}],"difficulty":1},{"id":"countable-uncountable-ex-16","type":"multiple_choice","question":"Choose the correct **quantity word**: Can I have a ___ of coffee?","options":["cup","many","rice","chairs"],"correct_answer":"cup","explanation":"“Coffee” là danh từ không đếm được, nên cần đơn vị đo như “a cup of coffee”. Các lựa chọn còn lại không tạo cụm danh từ đúng trong câu này.","distractor_breakdowns":[{"option":"cup","isCorrect":true,"pedagogicalReason":"“Coffee” là danh từ không đếm được, nên cần đơn vị đo như “a cup of coffee”. Các lựa chọn còn lại không tạo cụm danh từ đúng trong câu này."},{"option":"many","isCorrect":false,"pedagogicalReason":"Không chính xác. Phương án \"many\" không thỏa mãn quy tắc ngữ pháp hoặc sự hòa hợp cú pháp trong cấu trúc câu này."},{"option":"rice","isCorrect":false,"pedagogicalReason":"Không chính xác. Phương án \"rice\" không thỏa mãn quy tắc ngữ pháp hoặc sự hòa hợp cú pháp trong cấu trúc câu này."},{"option":"chairs","isCorrect":false,"pedagogicalReason":"Không chính xác. Phương án \"chairs\" không thỏa mãn quy tắc ngữ pháp hoặc sự hòa hợp cú pháp trong cấu trúc câu này."}],"difficulty":2},{"id":"countable-uncountable-ex-17","type":"multiple_choice","question":"Choose the correct **noun form**: I need two ___ for the classroom.","options":["chair","chairs","furniture","air"],"correct_answer":"chairs","explanation":"Sau số đếm “two”, dùng danh từ đếm được số nhiều: “chairs”. “Chair” là số ít, còn “furniture” và “air” là danh từ không đếm được.","distractor_breakdowns":[{"option":"chair","isCorrect":false,"pedagogicalReason":"Không chính xác. “Chair” là số ít, còn “furniture” và “air” là danh từ không đếm được."},{"option":"chairs","isCorrect":true,"pedagogicalReason":"Sau số đếm “two”, dùng danh từ đếm được số nhiều: “chairs”. “Chair” là số ít, còn “furniture” và “air” là danh từ không đếm được."},{"option":"furniture","isCorrect":false,"pedagogicalReason":"Không chính xác. “furniture” và “air” là danh từ không đếm được."},{"option":"air","isCorrect":false,"pedagogicalReason":"Không chính xác. “air” là danh từ không đếm được."}],"difficulty":1},{"id":"countable-uncountable-ex-18","type":"multiple_choice","question":"Choose the correct **question word**: How ___ sugar do you want?","options":["many","much","a","an"],"correct_answer":"much","explanation":"“Sugar” là danh từ không đếm được, nên hỏi số lượng bằng “How much”. “How many” dùng với danh từ đếm được số nhiều, còn “a/an” khôn