_breakdowns":[{"option":"loaves","isCorrect":true,"pedagogicalReason":"“Bread” thường là danh từ không đếm được, nên cần đơn vị đếm như “loaves”. “Bread” không dùng trực tiếp sau “two” ở nghĩa này; “many” và “informations” sai ngữ pháp."},{"option":"bread","isCorrect":false,"pedagogicalReason":"Không chính xác. “Bread” thường là danh từ không đếm được, nên cần đơn vị đếm như “loaves”."},{"option":"many","isCorrect":false,"pedagogicalReason":"Không chính xác. “many” và “informations” sai ngữ pháp."},{"option":"informations","isCorrect":false,"pedagogicalReason":"Không chính xác. “informations” sai ngữ pháp."}],"difficulty":2},{"id":"countable-uncountable-ex-21","type":"multiple_choice","question":"Choose the correct **noun type**: Which noun is uncountable?","options":["music","banana","ticket","window"],"correct_answer":"music","explanation":"“Music” là danh từ không đếm được trong tiếng Anh. “Banana”, “ticket” và “window” là danh từ đếm được vì có thể nói “one banana”, “two tickets”, “three windows”.","distractor_breakdowns":[{"option":"music","isCorrect":true,"pedagogicalReason":"“Music” là danh từ không đếm được trong tiếng Anh. “Banana”, “ticket” và “window” là danh từ đếm được vì có thể nói “one banana”, “two tickets”, “three windows”."},{"option":"banana","isCorrect":false,"pedagogicalReason":"Không chính xác. “Banana”, “ticket” và “window” là danh từ đếm được vì có thể nói “one banana”, “two tickets”, “three windows”."},{"option":"ticket","isCorrect":false,"pedagogicalReason":"Không chính xác. “ticket” và “window” là danh từ đếm được vì có thể nói “one banana”, “two tickets”, “three windows”."},{"option":"window","isCorrect":false,"pedagogicalReason":"Không chính xác. “window” là danh từ đếm được vì có thể nói “one banana”, “two tickets”, “three windows”."}],"difficulty":1},{"id":"countable-uncountable-ex-22","type":"fill_blank","question":"Fill in the correct **article**: She has ___ umbrella.","options":["a","an","some","many"],"correct_answer":"an","explanation":"“Umbrella” là danh từ đếm được số ít và bắt đầu bằng âm nguyên âm, nên dùng “an”. “A” dùng trước âm phụ âm; “some/many” không dùng cho danh từ số ít trong câu này.","distractor_breakdowns":[{"option":"a","isCorrect":false,"pedagogicalReason":"Không chính xác. “A” dùng trước âm phụ âm."},{"option":"an","isCorrect":true,"pedagogicalReason":"“Umbrella” là danh từ đếm được số ít và bắt đầu bằng âm nguyên âm, nên dùng “an”. “A” dùng trước âm phụ âm; “some/many” không dùng cho danh từ số ít trong câu này."},{"option":"some","isCorrect":false,"pedagogicalReason":"Không chính xác. Some/many” không dùng cho danh từ số ít trong câu này."},{"option":"many","isCorrect":false,"pedagogicalReason":"Không chính xác. Many” không dùng cho danh từ số ít trong câu này."}],"difficulty":1},{"id":"countable-uncountable-ex-23","type":"fill_blank","question":"Fill in the correct **quantifier**: There isn't ___ milk in the fridge.","options":["any","many","a","an"],"correct_answer":"any","explanation":"“Milk” là danh từ không đếm được; trong câu phủ định thường dùng “any”. “Many” dùng với danh từ đếm được số nhiều, còn “a/an” không dùng trực tiếp với “milk”.","distractor_breakdowns":[{"option":"any","isCorrect":true,"pedagogicalReason":"“Milk” là danh từ không đếm được; trong câu phủ định thường dùng “any”. “Many” dùng với danh từ đếm được số nhiều, còn “a/an” không dùng trực tiếp với “milk”."},{"option":"many","isCorrect":false,"pedagogicalReason":"Không chính xác. “Many” dùng với danh từ đếm được số nhiều, còn “a/an” không dùng trực tiếp với “milk”."},{"option":"a","isCorrect":false,"pedagogicalReason":"Không chính xác. A/an” không dùng trực tiếp với “milk”."},{"option":"an","isCorrect":false,"pedagogicalReason":"Không chính xác. An” không dùng trực tiếp với “milk”."}],"difficulty":1},{"id":"countable-uncountable-ex-24","type":"fill_blank","question":"Fill in the correct **plural form**: We need five ___ for the game.","options":["ball","balls","water","homework"],"correct_answer":